import React, { useState } from 'react';
import { Search, Filter, FlaskConical, Download, Eye, Calendar, User, Clock, FileText, BarChart3 } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './LabManagement.css';

const LabManagement = () => {
  const { data } = useData();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [selectedTest, setSelectedTest] = useState(null);

  // Mock lab tests data
  const labTests = [
    {
      id: '1',
      patientId: '1',
      testName: 'Complete Blood Count',
      testType: 'Hematology',
      orderedDate: '2024-01-18',
      status: 'completed',
      result: 'Normal',
      technician: 'Dr. Wilson',
      notes: 'Routine checkup'
    },
    {
      id: '2',
      patientId: '2',
      testName: 'Lipid Profile',
      testType: 'Biochemistry',
      orderedDate: '2024-01-19',
      status: 'in-progress',
      result: 'Pending',
      technician: 'Dr. Garcia',
      notes: 'Follow-up test'
    },
    {
      id: '3',
      patientId: '1',
      testName: 'Thyroid Panel',
      testType: 'Endocrinology',
      orderedDate: '2024-01-20',
      status: 'pending',
      result: 'Not Started',
      technician: '',
      notes: 'Suspected thyroid issues'
    },
    {
      id: '4',
      patientId: '3',
      testName: 'Liver Function Test',
      testType: 'Biochemistry',
      orderedDate: '2024-01-21',
      status: 'completed',
      result: 'Elevated ALT',
      technician: 'Dr. Wilson',
      notes: 'Monitor liver enzymes'
    },
    {
      id: '5',
      patientId: '2',
      testName: 'Urine Analysis',
      testType: 'Microscopy',
      orderedDate: '2024-01-22',
      status: 'in-progress',
      result: 'Pending',
      technician: 'Dr. Garcia',
      notes: 'Routine screening'
    }
  ];

  const filteredTests = labTests.filter(test => {
    const patient = data.patients.find(p => p.id === test.patientId);
    const matchesSearch = !searchTerm || 
      test.testName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient?.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient?.lastName.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesStatus = !filterStatus || test.status === filterStatus;
    
    return matchesSearch && matchesStatus;
  });

  const getStatusColor = (status) => {
    switch (status) {
      case 'completed': return 'badge-success';
      case 'in-progress': return 'badge-warning';
      case 'pending': return 'badge-info';
      default: return 'badge-info';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'completed': return 'Completed';
      case 'in-progress': return 'In Progress';
      case 'pending': return 'Pending';
      default: return status;
    }
  };

  const availableTests = [
    { name: 'Complete Blood Count', category: 'Hematology', price: 45 },
    { name: 'Lipid Profile', category: 'Biochemistry', price: 60 },
    { name: 'Liver Function Test', category: 'Biochemistry', price: 75 },
    { name: 'Thyroid Panel', category: 'Endocrinology', price: 85 },
    { name: 'Urine Analysis', category: 'Microscopy', price: 25 },
    { name: 'Blood Glucose', category: 'Biochemistry', price: 20 },
    { name: 'Kidney Function Test', category: 'Biochemistry', price: 65 },
    { name: 'Vitamin D Level', category: 'Endocrinology', price: 55 }
  ];

  // Calculate statistics
  const totalTests = labTests.length;
  const completedTests = labTests.filter(t => t.status === 'completed').length;
  const inProgressTests = labTests.filter(t => t.status === 'in-progress').length;
  const pendingTests = labTests.filter(t => t.status === 'pending').length;

  return (
    <div className="lab-management">
      {/* Header Section */}
      <div className="page-header">
        <h1>
          <FlaskConical size={32} style={{ marginRight: '12px' }} />
          Laboratory Management
        </h1>
        <p className="text-muted">Manage lab tests and results efficiently</p>
      </div>

      <div className="lab-content">
        {/* Main Content */}
        <div className="lab-main">
          {/* Filters Section */}
          <div className="filters-card">
            <div className="search-box">
              <Search size={20} className="search-icon" />
              <input
                type="text"
                placeholder="Search tests by name or patient..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="search-input"
              />
            </div>
            
            <div className="filter-group">
              <label style={{ fontWeight: '600', color: '#374151', marginBottom: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Filter size={16} />
                Test Status
              </label>
              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="filter-select"
              >
                <option value="">All Status</option>
                <option value="pending">⏳ Pending</option>
                <option value="in-progress">🔧 In Progress</option>
                <option value="completed">✅ Completed</option>
              </select>
            </div>
          </div>

          {/* Tests Table */}
          <div className="tests-table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>🧪 Test Name</th>
                  <th>👤 Patient</th>
                  <th>📊 Type</th>
                  <th>📅 Ordered Date</th>
                  <th>🔄 Status</th>
                  <th>🔧 Technician</th>
                  <th>⚡ Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredTests.map(test => {
                  const patient = data.patients.find(p => p.id === test.patientId);
                  return (
                    <tr key={test.id} onClick={() => setSelectedTest(test)} className="clickable-row">
                      <td>
                        <div className="test-info">
                          <FlaskConical size={18} />
                          <strong>{test.testName}</strong>
                        </div>
                      </td>
                      <td className="patient-name">
                        <User size={16} style={{ marginRight: '8px' }} />
                        {patient ? `${patient.firstName} ${patient.lastName}` : 'Unknown Patient'}
                      </td>
                      <td>
                        <span className="test-type">
                          {test.testType}
                        </span>
                      </td>
                      <td className="ordered-date">
                        <Calendar size={14} style={{ marginRight: '6px' }} />
                        {new Date(test.orderedDate).toLocaleDateString()}
                      </td>
                      <td>
                        <span className={`badge ${getStatusColor(test.status)}`}>
                          {getStatusText(test.status)}
                        </span>
                      </td>
                      <td className="technician-name">
                        {test.technician || 'Not assigned'}
                      </td>
                      <td>
                        <div className="action-buttons">
                          <button className="btn btn-outline btn-sm">
                            <Eye size={14} />
                            View
                          </button>
                          {test.status === 'completed' && (
                            <button className="btn btn-primary btn-sm">
                              <Download size={14} />
                              Report
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Horizontal Cards Row */}
          <div className="lab-cards-row">
            {/* Available Tests Card */}
            <div className="sidebar-card">
              <h3>
                <FileText size={20} />
                Available Tests
              </h3>
              <div className="tests-list">
                {availableTests.map((test, index) => (
                  <div key={index} className="test-item">
                    <div className="test-details">
                      <strong>{test.name}</strong>
                      <span className="test-category">{test.category}</span>
                    </div>
                    <div className="test-price">${test.price}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Test Details Card */}
            <div className="sidebar-card">
              <h3>
                <FlaskConical size={20} />
                Test Details
              </h3>
              <div className="test-detail-info">
                {selectedTest ? (
                  <>
                    <div className="detail-row">
                      <span>Test Name:</span>
                      <strong>{selectedTest.testName}</strong>
                    </div>
                    <div className="detail-row">
                      <span>Patient:</span>
                      <span>
                        {data.patients.find(p => p.id === selectedTest.patientId)?.firstName}{' '}
                        {data.patients.find(p => p.id === selectedTest.patientId)?.lastName}
                      </span>
                    </div>
                    <div className="detail-row">
                      <span>Type:</span>
                      <span>{selectedTest.testType}</span>
                    </div>
                    <div className="detail-row">
                      <span>Status:</span>
                      <span className={`badge ${getStatusColor(selectedTest.status)}`}>
                        {getStatusText(selectedTest.status)}
                      </span>
                    </div>
                    <div className="detail-row">
                      <span>Result:</span>
                      <span>{selectedTest.result}</span>
                    </div>
                    <div className="detail-row">
                      <span>Technician:</span>
                      <span>{selectedTest.technician || 'Not assigned'}</span>
                    </div>
                    <div className="detail-row">
                      <span>Ordered:</span>
                      <span>{new Date(selectedTest.orderedDate).toLocaleDateString()}</span>
                    </div>
                    {selectedTest.notes && (
                      <div className="detail-row">
                        <span>Notes:</span>
                        <span>{selectedTest.notes}</span>
                      </div>
                    )}
                  </>
                ) : (
                  <div style={{ textAlign: 'center', color: '#64748b', padding: '2rem' }}>
                    <FlaskConical size={48} style={{ marginBottom: '1rem', opacity: 0.5 }} />
                    <p>Select a test from the table to view details</p>
                  </div>
                )}
              </div>
            </div>

            {/* Quick Stats Card */}
            <div className="sidebar-card">
              <h3>
                <BarChart3 size={20} />
                Quick Stats
              </h3>
              <div className="stats-list">
                <div className="stat-item">
                  <span className="stat-value">{totalTests}</span>
                  <span className="stat-label">
                    <FileText size={16} />
                    Total Tests
                  </span>
                </div>
                <div className="stat-item">
                  <span className="stat-value">{completedTests}</span>
                  <span className="stat-label">
                    <Clock size={16} />
                    Completed
                  </span>
                </div>
                <div className="stat-item">
                  <span className="stat-value">{inProgressTests}</span>
                  <span className="stat-label">
                    <FlaskConical size={16} />
                    In Progress
                  </span>
                </div>
                <div className="stat-item">
                  <span className="stat-value">{pendingTests}</span>
                  <span className="stat-label">
                    <Calendar size={16} />
                    Pending
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LabManagement;