import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Calendar, Clock, User, Plus, Search, Calendar as CalendarIcon } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './AppointmentCalendar.css';

const AppointmentCalendar = () => {
  const { data, updateAppointment } = useData();
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [filterDoctor, setFilterDoctor] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredAppointments = data.appointments.filter(apt => {
    const matchesDate = apt.date === selectedDate;
    const matchesDoctor = !filterDoctor || apt.doctorId === filterDoctor;
    const matchesSearch = !searchTerm || 
      data.patients.find(p => p.id === apt.patientId)?.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      data.patients.find(p => p.id === apt.patientId)?.lastName.toLowerCase().includes(searchTerm.toLowerCase());
    
    return matchesDate && matchesDoctor && matchesSearch;
  });

  const handleStatusUpdate = (appointmentId, newStatus) => {
    updateAppointment(appointmentId, { status: newStatus });
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'scheduled': return '#3b82f6';
      case 'completed': return '#10b981';
      case 'cancelled': return '#ef4444';
      default: return '#6b7280';
    }
  };

  const groupedAppointments = filteredAppointments.reduce((groups, apt) => {
    const time = apt.time;
    if (!groups[time]) {
      groups[time] = [];
    }
    groups[time].push(apt);
    return groups;
  }, {});

  return (
    <div className="appointment-calendar">
      {/* Header Section */}
      <div className="calendar-header">
        <div className="title-section">
  <CalendarIcon size={40} className="header-icon" />
  <div className="title-group">
    <h1>Appointment Calendar</h1>
    <p className="text-muted">
      {new Date(selectedDate).toLocaleDateString('en-US', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      })}
    </p>
  </div>
</div>
      </div>

      {/* Stats Section - Horizontal Small Boxes */}
      <div className="stats-section">
        <div className="stat-box scheduled">
          <span className="stat-number">
            {filteredAppointments.filter(apt => apt.status === 'scheduled').length}
          </span>
          <span className="stat-label">Scheduled</span>
        </div>
        <div className="stat-box completed">
          <span className="stat-number">
            {filteredAppointments.filter(apt => apt.status === 'completed').length}
          </span>
          <span className="stat-label">Completed</span>
        </div>
        <div className="stat-box cancelled">
          <span className="stat-number">
            {filteredAppointments.filter(apt => apt.status === 'cancelled').length}
          </span>
          <span className="stat-label">Cancelled</span>
        </div>
      </div>

      {/* New Appointment Section */}
      <div className="new-appointment-section">
        <Link to="/appointments/schedule" className="new-appointment-btn">
          <Plus size={20} />
          <span>New Appointment</span>
        </Link>
      </div>

      {/* Controls Section */}
      <div className="calendar-controls">
        <div className="control-group">
          <div className="control-item">
            <label htmlFor="date" className="form-label">Select Date</label>
            <input
              type="date"
              id="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="form-control"
            />
          </div>

          <div className="control-item">
            <label htmlFor="doctor" className="form-label">Filter by Doctor</label>
            <select
              id="doctor"
              value={filterDoctor}
              onChange={(e) => setFilterDoctor(e.target.value)}
              className="form-control"
            >
              <option value="">All Doctors</option>
              {data.doctors.map(doctor => (
                <option key={doctor.id} value={doctor.id}>
                  {doctor.name}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="search-container">
          <label htmlFor="search" className="form-label">Search Patients</label>
          <div className="search-box">
            <Search size={20} className="search-icon" />
            <input
              type="text"
              id="search"
              placeholder="Search by patient name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
        </div>
      </div>

      {/* Main Content - Horizontal Layout */}
      <div className="calendar-content">
        <div className="calendar-view">
          {Object.keys(groupedAppointments).length > 0 ? (
            <div className="time-slots">
              {Object.entries(groupedAppointments)
                .sort(([timeA], [timeB]) => timeA.localeCompare(timeB))
                .map(([time, appointments]) => (
                  <div key={time} className="time-slot-group">
                    <div className="time-header">
                      <Clock size={18} />
                      <span>{time}</span>
                      <span className="appointment-count">
                        {appointments.length} appointment{appointments.length !== 1 ? 's' : ''}
                      </span>
                    </div>
                    <div className="appointments-list">
                      {appointments.map(appointment => {
                        const patient = data.patients.find(p => p.id === appointment.patientId);
                        const doctor = data.doctors.find(d => d.id === appointment.doctorId);
                        
                        return (
                          <div key={appointment.id} className="appointment-card">
                            <div className="appointment-info">
                              <div className="patient-info">
                                <div className="patient-avatar">
                                  <User size={20} />
                                </div>
                                <div>
                                  <h4 className="patient-name">
                                    {patient ? `${patient.firstName} ${patient.lastName}` : 'Unknown Patient'}
                                  </h4>
                                  <span className="appointment-type">{appointment.type}</span>
                                  <div className="doctor-info">
                                    With Dr. {doctor?.name || 'Unknown Doctor'}
                                  </div>
                                </div>
                              </div>
                              
                              {appointment.notes && (
                                <div className="appointment-notes">
                                  <p>{appointment.notes}</p>
                                </div>
                              )}
                            </div>
                            
                            <div className="appointment-actions">
                              <div 
                                className="status-badge"
                                style={{ backgroundColor: getStatusColor(appointment.status) }}
                              >
                                {appointment.status}
                              </div>
                              
                              {appointment.status === 'scheduled' && (
                                <div className="action-buttons">
                                  <button
                                    onClick={() => handleStatusUpdate(appointment.id, 'completed')}
                                    className="btn btn-success"
                                  >
                                    Complete
                                  </button>
                                  <button
                                    onClick={() => handleStatusUpdate(appointment.id, 'cancelled')}
                                    className="btn btn-error"
                                  >
                                    Cancel
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))
              }
            </div>
          ) : (
            <div className="empty-state">
              <Calendar size={64} className="empty-icon" />
              <h3>No appointments scheduled</h3>
              <p>There are no appointments scheduled for the selected date and filters.</p>
              <Link to="/appointments/schedule" className="btn btn-primary">
                <Plus size={16} />
                Schedule Appointment
              </Link>
            </div>
          )}
        </div>

        {/* Sidebar Stats */}
        <div className="sidebar-stats">
          <div className="sidebar-stat scheduled">
            <span className="stat-number">
              {filteredAppointments.filter(apt => apt.status === 'scheduled').length}
            </span>
            <span className="stat-label">Scheduled</span>
          </div>
          <div className="sidebar-stat completed">
            <span className="stat-number">
              {filteredAppointments.filter(apt => apt.status === 'completed').length}
            </span>
            <span className="stat-label">Completed</span>
          </div>
          <div className="sidebar-stat cancelled">
            <span className="stat-number">
              {filteredAppointments.filter(apt => apt.status === 'cancelled').length}
            </span>
            <span className="stat-label">Cancelled</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AppointmentCalendar;