// src/components/pages/Gallery.js
import React, { useState } from 'react';
import { Search, Filter, X, ZoomIn, ArrowLeft, ArrowRight, Download, Share2, Heart } from 'lucide-react';

const Gallery = () => {
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedImage, setSelectedImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const galleryCategories = [
    { id: 'all', name: 'All Photos', count: 28, color: '#3B82F6' },
    { id: 'facilities', name: 'Medical Facilities', count: 12, color: '#10B981' },
    { id: 'technology', name: 'Advanced Technology', count: 8, color: '#8B5CF6' },
    { id: 'team', name: 'Medical Team', count: 6, color: '#EF4444' },
    { id: 'surgery', name: 'Operation Theaters', count: 4, color: '#F59E0B' },
    { id: 'patient-care', name: 'Patient Care', count: 6, color: '#06B6D4' }
  ];

  const galleryImages = [
    // Medical Facilities Images
    {
      id: 1,
      category: 'facilities',
      title: 'Modern Hospital Building',
      description: 'State-of-the-art hospital infrastructure with advanced medical facilities',
      src: 'https://img.freepik.com/premium-photo/modern-hospital-building-with-glass-exteriors-medical-facilities-generative-ai_288945-1510.jpg?w=740',
      alt: 'Care Connect Hospital Building',
      featured: true
    },
    {
      id: 2,
      category: 'facilities',
      title: 'Emergency Department',
      description: '24/7 emergency care unit with modern life-saving equipment',
      src: 'https://thumbs.dreamstime.com/b/calgary-alberta-canada-feb-primary-entrance-to-emergency-section-football-hospital-307844177.jpg',
      alt: 'Emergency Department'
    },
    {
      id: 3,
      category: 'facilities',
      title: 'ICU Unit',
      description: 'Intensive Care Unit with advanced patient monitoring systems',
      src: 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80',
      alt: 'ICU Unit'
    },
    {
      id: 4,
      category: 'facilities',
      title: 'Patient Rooms',
      description: 'Comfortable and hygienic patient rooms for better recovery',
      src: 'https://www.stinabooth.com/wp-content/uploads/2018/01/011medicalarchitecturegallery-stinabooth17.jpg',
      alt: 'Patient Rooms'
    },

    // Advanced Technology Images
    {
      id: 5,
      category: 'technology',
      title: 'MRI Scanning Machine',
      description: 'Advanced 3T MRI machine for precise diagnostic imaging',
      src: 'https://www.hrh.ca/wp-content/uploads/2023/03/MRI.jpg',
      alt: 'MRI Machine'
    },
    {
      id: 6,
      category: 'technology',
      title: 'Robotic Surgery System',
      description: 'Da Vinci robotic surgery system for minimally invasive procedures',
      src: 'https://www.pvhmc.org/images/robotic-surgery.jpg',
      alt: 'Robotic Surgery'
    },


    // Medical Team Images
    {
      id: 8,
      category: 'team',
      title: 'Cardiology Team',
      description: 'Our expert cardiology department with senior consultants',
      src: 'https://images.unsplash.com/photo-1551601651-2a8555f1a136?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80',
      alt: 'Cardiology Team'
    },
    {
      id: 9,
      category: 'team',
      title: 'Surgical Team',
      description: 'Experienced surgical team performing complex procedures',
      src: 'http://il9.picdn.net/shutterstock/videos/3782069/thumb/1.jpg',
      alt: 'Surgical Team'
    },

    // Operation Theaters Images
    {
      id: 10,
      category: 'surgery',
      title: 'Digital Operation Theater',
      description: 'Advanced digital OT with integrated monitoring systems',
      src: 'https://www.jupiterhospital.com/wp-content/uploads/2022/12/Thane-cardiac-ot.jpg',
      alt: 'Operation Theater'
    },
    {
      id: 11,
      category: 'surgery',
      title: 'Cardiac Surgery',
      description: 'Modern cardiac surgery setup with life support systems',
      src: 'https://storage.googleapis.com/jacksonh/1/Cardiology_Comprehensive-Care-Heart-1.jpg',
      alt: 'Cardiac Surgery'
    },

    // Patient Care Images
    {
      id: 12,
      category: 'patient-care',
      title: 'Pediatric Care',
      description: 'Specialized care for our young patients in colorful environment',
      src: 'https://www.doctorsfinder.in/wp-content/uploads/2021/12/pediatric-hospitals-in-India.jpg',
      alt: 'Pediatric Care'
    },
    {
      id: 14,
      category: 'patient-care',
      title: 'Maternity Ward',
      description: 'Comfortable maternity care with modern facilities',
      src: 'https://www.wollongongprivate.com.au/-/media/Content-Images/WGP/Maternity/2024/240223_00041.jpg',
      alt: 'Maternity Ward'
    }
  ];

  // Filter images based on category and search
  const filteredImages = galleryImages.filter(image => {
    const matchesCategory = selectedCategory === 'all' || image.category === selectedCategory;
    const matchesSearch = image.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         image.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const currentCategory = galleryCategories.find(cat => cat.id === selectedCategory);

  const openLightbox = (image) => {
    setSelectedImage(image);
  };

  const closeLightbox = () => {
    setSelectedImage(null);
  };

  const navigateImage = (direction) => {
    if (!selectedImage) return;
    
    const currentIndex = filteredImages.findIndex(img => img.id === selectedImage.id);
    let newIndex;
    
    if (direction === 'next') {
      newIndex = (currentIndex + 1) % filteredImages.length;
    } else {
      newIndex = (currentIndex - 1 + filteredImages.length) % filteredImages.length;
    }
    
    setSelectedImage(filteredImages[newIndex]);
  };

  return (
    <div className="gallery-page" style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
      padding: '2rem 0'
    }}>
      {/* Header Section */}
      <div className="container" style={{ 
        maxWidth: '1400px', 
        margin: '0 auto', 
        padding: '0 1rem' 
      }}>
        <div className="page-header" style={{ 
          textAlign: 'center', 
          marginBottom: '3rem' 
        }}>
          <h1 style={{ 
            fontSize: 'clamp(2.5rem, 6vw, 4.5rem)', 
            fontWeight: '900',
            background: 'linear-gradient(45deg, #f7f7f8ff, #f8fafbff)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
            backgroundClip: 'text',
            marginBottom: '1rem',
            lineHeight: '1.2'
          }}>
            Our Medical Gallery
          </h1>
          

          {/* Search Bar */}
          <div style={{
            maxWidth: '500px',
            margin: '0 auto 2rem',
            position: 'relative'
          }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              background: 'white',
              borderRadius: '50px',
              padding: '0.75rem 1.5rem',
              boxShadow: '0 4px 15px rgba(0, 0, 0, 0.1)',
              border: '2px solid #e2e8f0'
            }}>
              <Search size={20} color="#64748b" style={{ marginRight: '0.75rem' }} />
              <input
                type="text"
                placeholder="Search images by title or description..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{
                  border: 'none',
                  outline: 'none',
                  fontSize: '1rem',
                  width: '100%',
                  background: 'transparent'
                }}
              />
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm('')}
                  style={{
                    background: 'none',
                    border: 'none',
                    cursor: 'pointer',
                    padding: '0.25rem'
                  }}
                >
                  <X size={18} color="#64748b" />
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Category Filter */}
        <div className="category-filter" style={{
          display: 'flex',
          justifyContent: 'center',
          flexWrap: 'wrap',
          gap: '1rem',
          marginBottom: '3rem'
        }}>
          {galleryCategories.map(category => (
            <button
              key={category.id}
              onClick={() => setSelectedCategory(category.id)}
              style={{
                background: selectedCategory === category.id ? category.color : 'white',
                color: selectedCategory === category.id ? 'white' : '#64748b',
                border: `2px solid ${category.color}`,
                padding: '0.75rem 1.5rem',
                borderRadius: '50px',
                fontSize: '0.9rem',
                fontWeight: '600',
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                display: 'flex',
                alignItems: 'center',
                gap: '0.5rem'
              }}
            >
              <Filter size={16} />
              {category.name}
              <span style={{
                background: selectedCategory === category.id ? 'rgba(255,255,255,0.2)' : `${category.color}15`,
                color: selectedCategory === category.id ? 'white' : category.color,
                padding: '0.25rem 0.5rem',
                borderRadius: '20px',
                fontSize: '0.8rem',
                fontWeight: '700'
              }}>
                {category.count}
              </span>
            </button>
          ))}
        </div>

        {/* Results Count */}
        <div style={{ 
          textAlign: 'center', 
          marginBottom: '2rem' 
        }}>
          <h2 style={{ 
            fontSize: 'clamp(1.5rem, 4vw, 2.2rem)',
            color: '#1e293b',
            marginBottom: '0.5rem',
            fontWeight: '700'
          }}>
            {currentCategory?.name}
          </h2>
          <p style={{ 
            color: '#64748b',
            fontSize: '1.1rem',
            margin: 0
          }}>
            Showing {filteredImages.length} of {galleryImages.length} images
          </p>
        </div>

        {/* Gallery Grid */}
        <div className="gallery-grid" style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
          gap: '1.5rem',
          marginBottom: '3rem'
        }}>
          {filteredImages.map((image, index) => (
            <div
              key={image.id}
              className="gallery-item"
              style={{
                background: 'white',
                borderRadius: '16px',
                overflow: 'hidden',
                boxShadow: '0 6px 20px rgba(0, 0, 0, 0.1)',
                border: '2px solid #e2e8f0',
                transition: 'all 0.3s ease',
                cursor: 'pointer',
                position: 'relative'
              }}
              onClick={() => openLightbox(image)}
            >
              {/* Image Display */}
              <div style={{
                width: '100%',
                height: '250px',
                background: `linear-gradient(135deg, ${galleryCategories.find(cat => cat.id === image.category)?.color}20, ${galleryCategories.find(cat => cat.id === image.category)?.color}40)`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                position: 'relative',
                overflow: 'hidden'
              }}>
                <img 
                  src={image.src} 
                  alt={image.alt}
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    transition: 'transform 0.3s ease'
                  }}
                  onError={(e) => {
                    // Fallback to placeholder if image fails to load
                    e.target.style.display = 'none';
                    const placeholder = document.createElement('div');
                    placeholder.style.cssText = `
                      width: 100%;
                      height: 100%;
                      display: flex;
                      align-items: center;
                      justify-content: center;
                      font-size: 3rem;
                      color: ${galleryCategories.find(cat => cat.id === image.category)?.color};
                      background: linear-gradient(135deg, ${galleryCategories.find(cat => cat.id === image.category)?.color}20, ${galleryCategories.find(cat => cat.id === image.category)?.color}40);
                    `;
                    placeholder.innerHTML = `
                      <div style="text-align: center;">
                        <div style="font-size: 4rem; margin-bottom: 0.5rem;">
                          ${image.category === 'facilities' ? '🏥' : 
                            image.category === 'technology' ? '🔬' : 
                            image.category === 'team' ? '👨‍⚕️' : 
                            image.category === 'surgery' ? '⚕️' : '❤️'}
                        </div>
                        <div style="background: rgba(255,255,255,0.9); padding: 0.5rem 1rem; border-radius: 8px; font-size: 0.8rem; font-weight: 600; color: ${galleryCategories.find(cat => cat.id === image.category)?.color}">
                          ${image.title}
                        </div>
                      </div>
                    `;
                    e.target.parentNode.appendChild(placeholder);
                  }}
                />
                
                {/* Hover Overlay */}
                <div style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background: 'rgba(0,0,0,0.7)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  opacity: 0,
                  transition: 'opacity 0.3s ease'
                }}>
                  <ZoomIn size={32} color="white" />
                </div>
              </div>

              {/* Image Info */}
              <div style={{ padding: '1.5rem' }}>
                <h3 style={{
                  margin: '0 0 0.5rem 0',
                  fontSize: '1.2rem',
                  fontWeight: '700',
                  color: '#1e293b'
                }}>
                  {image.title}
                </h3>
                <p style={{
                  margin: '0 0 1rem 0',
                  color: '#64748b',
                  fontSize: '0.9rem',
                  lineHeight: '1.5'
                }}>
                  {image.description}
                </p>
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between'
                }}>
                  <span style={{
                    background: `${galleryCategories.find(cat => cat.id === image.category)?.color}15`,
                    color: galleryCategories.find(cat => cat.id === image.category)?.color,
                    padding: '0.25rem 0.75rem',
                    borderRadius: '20px',
                    fontSize: '0.8rem',
                    fontWeight: '600'
                  }}>
                    {galleryCategories.find(cat => cat.id === image.category)?.name}
                  </span>
                  {image.featured && (
                    <span style={{
                      background: '#F59E0B15',
                      color: '#D97706',
                      padding: '0.25rem 0.75rem',
                      borderRadius: '20px',
                      fontSize: '0.8rem',
                      fontWeight: '600'
                    }}>
                      ⭐ Featured
                    </span>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* No Results Message */}
        {filteredImages.length === 0 && (
          <div style={{ 
            textAlign: 'center', 
            padding: '4rem 2rem',
            background: 'white',
            borderRadius: '16px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
          }}>
            <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>🔍</div>
            <h3 style={{ 
              fontSize: '1.8rem', 
              color: '#1e293b',
              marginBottom: '0.5rem'
            }}>
              No images found
            </h3>
            <p style={{ 
              color: '#64748b',
              fontSize: '1.1rem',
              marginBottom: '2rem'
            }}>
              Try adjusting your search or filter criteria
            </p>
            <button
              onClick={() => {
                setSearchTerm('');
                setSelectedCategory('all');
              }}
              style={{
                background: 'linear-gradient(135deg, #1e40af, #dc2626)',
                color: 'white',
                border: 'none',
                padding: '1rem 2rem',
                borderRadius: '12px',
                fontSize: '1rem',
                fontWeight: '600',
                cursor: 'pointer'
              }}
            >
              Show All Images
            </button>
          </div>
        )}
      </div>

      {/* Lightbox Modal */}
      {selectedImage && (
        <div className="lightbox" style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.95)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000,
          padding: '2rem'
        }}>
          <div className="lightbox-content" style={{
            maxWidth: '90vw',
            maxHeight: '90vh',
            position: 'relative'
          }}>
            {/* Close Button */}
            <button
              onClick={closeLightbox}
              style={{
                position: 'absolute',
                top: '-50px',
                right: '0',
                background: 'rgba(255,255,255,0.1)',
                border: 'none',
                color: 'white',
                padding: '0.75rem',
                borderRadius: '50%',
                cursor: 'pointer',
                zIndex: 1001
              }}
            >
              <X size={24} />
            </button>

            {/* Navigation Arrows */}
            <button
              onClick={() => navigateImage('prev')}
              style={{
                position: 'absolute',
                left: '-60px',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'rgba(255,255,255,0.1)',
                border: 'none',
                color: 'white',
                padding: '1rem',
                borderRadius: '50%',
                cursor: 'pointer'
              }}
            >
              <ArrowLeft size={24} />
            </button>

            <button
              onClick={() => navigateImage('next')}
              style={{
                position: 'absolute',
                right: '-60px',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'rgba(255,255,255,0.1)',
                border: 'none',
                color: 'white',
                padding: '1rem',
                borderRadius: '50%',
                cursor: 'pointer'
              }}
            >
              <ArrowRight size={24} />
            </button>

            {/* Image Content */}
            <div style={{
              background: 'white',
              borderRadius: '16px',
              overflow: 'hidden',
              maxWidth: '800px'
            }}>
              <div style={{
                width: '100%',
                height: '400px',
                position: 'relative',
                overflow: 'hidden'
              }}>
                <img 
                  src={selectedImage.src} 
                  alt={selectedImage.alt}
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover'
                  }}
                  onError={(e) => {
                    e.target.style.display = 'none';
                    const placeholder = document.createElement('div');
                    placeholder.style.cssText = `
                      width: 100%;
                      height: 100%;
                      display: flex;
                      align-items: center;
                      justify-content: center;
                      font-size: 4rem;
                      background: linear-gradient(135deg, ${galleryCategories.find(cat => cat.id === selectedImage.category)?.color}20, ${galleryCategories.find(cat => cat.id === selectedImage.category)?.color}40);
                    `;
                    placeholder.innerHTML = `
                      ${selectedImage.category === 'facilities' ? '🏥' : 
                        selectedImage.category === 'technology' ? '🔬' : 
                        selectedImage.category === 'team' ? '👨‍⚕️' : 
                        selectedImage.category === 'surgery' ? '⚕️' : '❤️'}
                    `;
                    e.target.parentNode.appendChild(placeholder);
                  }}
                />
              </div>
              
              <div style={{ padding: '2rem' }}>
                <h2 style={{ 
                  margin: '0 0 1rem 0',
                  fontSize: '1.8rem',
                  fontWeight: '700',
                  color: '#1e293b'
                }}>
                  {selectedImage.title}
                </h2>
                <p style={{ 
                  margin: '0 0 1.5rem 0',
                  color: '#64748b',
                  fontSize: '1.1rem',
                  lineHeight: '1.6'
                }}>
                  {selectedImage.description}
                </p>
                <div style={{
                  display: 'flex',
                  gap: '1rem',
                  alignItems: 'center'
                }}>
                  <span style={{
                    background: `${galleryCategories.find(cat => cat.id === selectedImage.category)?.color}15`,
                    color: galleryCategories.find(cat => cat.id === selectedImage.category)?.color,
                    padding: '0.5rem 1rem',
                    borderRadius: '20px',
                    fontSize: '0.9rem',
                    fontWeight: '600'
                  }}>
                    {galleryCategories.find(cat => cat.id === selectedImage.category)?.name}
                  </span>
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button style={{
                      background: '#f1f5f9',
                      border: 'none',
                      padding: '0.5rem 1rem',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.5rem'
                    }}>
                      <Heart size={16} />
                      Like
                    </button>
                    <button style={{
                      background: '#f1f5f9',
                      border: 'none',
                      padding: '0.5rem 1rem',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.5rem'
                    }}>
                      <Share2 size={16} />
                      Share
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        .gallery-item:hover {
          transform: translateY(-8px);
          box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
        }

        .gallery-item:hover > div:first-child > div:last-child {
          opacity: 1;
        }

        .gallery-item:hover img {
          transform: scale(1.05);
        }

        @media (max-width: 768px) {
          .gallery-grid {
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 1rem;
          }

          .category-filter {
            gap: 0.5rem;
          }

          .category-filter button {
            padding: 0.6rem 1rem;
            font-size: 0.8rem;
          }

          .lightbox-content {
            max-width: 95vw;
          }
        }

        @media (max-width: 480px) {
          .gallery-grid {
            grid-template-columns: 1fr;
          }

          .page-header h1 {
            font-size: 2rem !important;
          }

          .page-header p {
            font-size: 1rem !important;
          }

          .lightbox {
            padding: 1rem;
          }
        }

        @media (max-width: 360px) {
          .container {
            padding: 0 0.5rem;
          }
          
          .gallery-item > div:first-child {
            height: 200px;
          }
        }
      `}</style>
    </div>
  );
};

export default Gallery;