import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Search, UserPlus, Eye, Edit, Phone, Mail } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './PatientList.css';

const PatientList = () => {
  const { data } = useData();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterGender, setFilterGender] = useState('');

  const filteredPatients = data.patients.filter(patient => {
    const matchesSearch = 
      patient.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient.patientId?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient.phone.includes(searchTerm);
    
    const matchesGender = !filterGender || patient.gender === filterGender;
    
    return matchesSearch && matchesGender;
  });

  const formatPhone = (phone) => {
    return phone.replace(/(\d{3})(\d{3})(\d{4})/, '($1) $2-$3');
  };

  return (
    <div className="patient-list">
      {/* Main Header Section */}
      <div className="page-header-main">
        <div className="header-content">
          <div className="header-text" style={{textAlign: 'center', flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
  <h1 className="main-title" style={{fontSize: '3rem', marginBottom: '0.125rem', textAlign: 'center'}}>Patient List</h1>
  <p className="header-subtitle" style={{fontSize: '0.8rem', textAlign: 'center'}}>Healthcare Management System</p>
</div>
          
        </div>
      </div>

      {/* Action Bar */}
      <div className="action-bar">
        <div className="action-left">
          <Link to="/patients/registration" className="btn btn-primary add-patient-btn">
            <UserPlus size={18} />
            Add New Patient
          </Link>
        </div>
        <div className="action-right">
          <div className="quick-stats">
            <span className="quick-stat">Total: {data.patients.length}</span>
            <span className="quick-stat">Active: {data.patients.length}</span>
          </div>
        </div>
      </div>

      {/* Search and Filters Section */}
      <div className="search-section">
        <div className="filters-card">
          <div className="search-box">
            <Search size={20} className="search-icon" />
            <input
              type="text"
              placeholder="Search patients by name, ID, or phone..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
          
          <div className="filter-group">
            <select
              value={filterGender}
              onChange={(e) => setFilterGender(e.target.value)}
              className="filter-select"
            >
              <option value="">All Genders</option>
              <option value="Male">Male</option>
              <option value="Female">Female</option>
              <option value="Other">Other</option>
            </select>
          </div>
        </div>
      </div>

      {/* Patients Grid */}
      <div className="patients-grid">
        {filteredPatients.length > 0 ? (
          filteredPatients.map(patient => (
            <div key={patient.id} className="patient-card">
              <div className="patient-header">
                <div className="patient-avatar">
                  {patient.firstName[0]}{patient.lastName[0]}
                </div>
                <div className="patient-info">
                  <h3>{patient.firstName} {patient.lastName}</h3>
                  <p className="patient-id">ID: {patient.patientId || `PT${patient.id.slice(-4)}`}</p>
                </div>
              </div>

              <div className="patient-details">
                <div className="detail-item">
                  <Phone size={16} />
                  <span>{formatPhone(patient.phone)}</span>
                </div>
                {patient.email && (
                  <div className="detail-item">
                    <Mail size={16} />
                    <span>{patient.email}</span>
                  </div>
                )}
                <div className="detail-item">
                  <span>Gender:</span>
                  <span className="detail-value">{patient.gender}</span>
                </div>
                <div className="detail-item">
                  <span>Age:</span>
                  <span className="detail-value">
                    {patient.dob ? new Date().getFullYear() - new Date(patient.dob).getFullYear() : 'N/A'}
                  </span>
                </div>
                {patient.bloodGroup && (
                  <div className="detail-item">
                    <span>Blood Group:</span>
                    <span className="detail-value">{patient.bloodGroup}</span>
                  </div>
                )}
              </div>

              <div className="patient-actions">
                <Link 
                  to={`/appointments/schedule?patientId=${patient.id}`}
                  className="btn btn-outline btn-sm"
                >
                  <Eye size={14} />
                  View
                </Link>
                <button className="btn btn-outline btn-sm">
                  <Edit size={14} />
                  Edit
                </button>
              </div>
            </div>
          ))
        ) : (
          <div className="empty-state">
            <div className="empty-icon">
              <Search size={48} />
            </div>
            <h3>No patients found</h3>
            <p>
              {searchTerm || filterGender 
                ? 'Try adjusting your search criteria' 
                : 'Get started by registering your first patient'
              }
            </p>
            {!searchTerm && !filterGender && (
              <Link to="/patients/registration" className="btn btn-primary">
                <UserPlus size={16} />
                Register First Patient
              </Link>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default PatientList;