import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { Calendar, Clock, User, ArrowLeft, Save, Stethoscope, Phone, Mail } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './AppointmentScheduler.css';

const AppointmentScheduler = () => {
  const { data, addAppointment } = useData();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [formData, setFormData] = useState({
    patientId: searchParams.get('patientId') || '',
    doctorId: '',
    date: '',
    time: '',
    type: 'Consultation',
    notes: ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [availableSlots, setAvailableSlots] = useState([]);

  const appointmentTypes = [
    'Consultation',
    'Follow-up',
    'Checkup',
    'Emergency',
    'Surgery',
    'Therapy',
    'Lab Test',
    'Vaccination'
  ];

  const timeSlots = [
    '08:00', '08:30', '09:00', '09:30', '10:00', '10:30',
    '11:00', '11:30', '12:00', '12:30', '13:00', '13:30',
    '14:00', '14:30', '15:00', '15:30', '16:00', '16:30',
    '17:00', '17:30'
  ];

  // Update available slots when doctor or date changes
  useEffect(() => {
    if (formData.doctorId && formData.date) {
      const doctor = data.doctors.find(d => d.id === formData.doctorId);
      const dayOfWeek = new Date(formData.date).getDay();
      const doctorSchedule = doctor?.schedule?.[dayOfWeek] || [];
      
      const bookedSlots = data.appointments
        .filter(apt => 
          apt.doctorId === formData.doctorId &&
          apt.date === formData.date &&
          apt.status !== 'cancelled'
        )
        .map(apt => apt.time);

      const available = timeSlots.map(slot => ({
        time: slot,
        available: !bookedSlots.includes(slot) && doctorSchedule.includes(slot),
        booked: bookedSlots.includes(slot)
      }));

      setAvailableSlots(available);
    } else {
      setAvailableSlots([]);
    }
  }, [formData.doctorId, formData.date, data.doctors, data.appointments]);

  const validateForm = () => {
    const newErrors = {};
    
    if (!formData.patientId) newErrors.patientId = 'Please select a patient';
    if (!formData.doctorId) newErrors.doctorId = 'Please select a doctor';
    if (!formData.date) newErrors.date = 'Please select a date';
    if (!formData.time) newErrors.time = 'Please select a time';
    
    // Check for conflicting appointments
    const conflict = data.appointments.find(apt => 
      apt.doctorId === formData.doctorId &&
      apt.date === formData.date &&
      apt.time === formData.time &&
      apt.status !== 'cancelled'
    );
    
    if (conflict) {
      newErrors.time = 'This time slot is already booked for the selected doctor';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleTimeSlotClick = (time, available) => {
    if (available) {
      setFormData(prev => ({ ...prev, time }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);
    
    setTimeout(() => {
      const newAppointment = addAppointment({
        ...formData,
        status: 'scheduled',
        id: Date.now().toString(),
        createdAt: new Date().toISOString()
      });
      
      setIsSubmitting(false);
      alert('✅ Appointment scheduled successfully!');
      navigate('/appointments/calendar');
    }, 1000);
  };

  const selectedPatient = data.patients.find(p => p.id === formData.patientId);
  const selectedDoctor = data.doctors.find(d => d.id === formData.doctorId);

  // Set minimum date to today
  const today = new Date().toISOString().split('T')[0];

  return (
    <div className="appointment-scheduler">
      {/* Header Section */}
      <div className="page-header">
        <div className="header-left">
          <Link to="/appointments/calendar" className="btn btn-outline">
            <ArrowLeft size={20} />
            Back to Calendar
          </Link>
          <Calendar 
    size={28} 
    style={{ 
      position: 'absolute',
      left: '370px',  /* Change this value to move icon left/right */
      color: 'white'
    }} 
  />
  <h1 style={{ 
    marginLeft: '150px',  /* Change this value to move text left/right */
    color: 'white'
  }}>
    Schedule Appointment
  </h1>
        </div>
      </div>

      {/* Main Form Card */}
      <div className="scheduler-container">
        <div className="scheduler-card">
          <div className="card-header">
            <div className="header-title">
              <Stethoscope size={32} color="white" />
              <h2>New Medical Appointment</h2>
            </div>
            <p className="text-muted">
              Schedule a new appointment for patient care and consultation
            </p>
          </div>

          <form onSubmit={handleSubmit} className="scheduler-form">
            {/* Patient Information Section */}
            <div className="form-section">
              <h3>
                <User size={24} />
                Patient Information
              </h3>
              
              <div className="form-group">
                <label htmlFor="patientId" className="form-label">
                  Select Patient
                </label>
                <select
                  id="patientId"
                  name="patientId"
                  value={formData.patientId}
                  onChange={handleChange}
                  className={`form-control ${errors.patientId ? 'error' : ''}`}
                  required
                >
                  <option value="">Choose a patient...</option>
                  {data.patients.map(patient => (
                    <option key={patient.id} value={patient.id}>
                      {patient.firstName} {patient.lastName} - {patient.phone}
                    </option>
                  ))}
                </select>
                {errors.patientId && (
                  <div className="form-error">{errors.patientId}</div>
                )}
              </div>

              {selectedPatient && (
                <div className="patient-preview">
                  <div className="preview-header">
                    <User size={20} />
                    <span>Selected Patient Details</span>
                  </div>
                  <div className="preview-details">
                    <strong>{selectedPatient.firstName} {selectedPatient.lastName}</strong>
                    <span>
                      <Phone size={16} />
                      {selectedPatient.phone}
                    </span>
                    {selectedPatient.email && (
                      <span>
                        <Mail size={16} />
                        {selectedPatient.email}
                      </span>
                    )}
                    {selectedPatient.gender && (
                      <span>Gender: {selectedPatient.gender}</span>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Appointment Details Section */}
            <div className="form-section">
              <h3>
                <Calendar size={24} />
                Appointment Details
              </h3>
              
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="doctorId" className="form-label">
                    Healthcare Provider
                  </label>
                  <select
                    id="doctorId"
                    name="doctorId"
                    value={formData.doctorId}
                    onChange={handleChange}
                    className={`form-control ${errors.doctorId ? 'error' : ''}`}
                    required
                  >
                    <option value="">Select medical professional...</option>
                    {data.doctors.map(doctor => (
                      <option key={doctor.id} value={doctor.id}>
                        Dr. {doctor.name} - {doctor.specialization}
                      </option>
                    ))}
                  </select>
                  {errors.doctorId && (
                    <div className="form-error">{errors.doctorId}</div>
                  )}
                </div>

                <div className="form-group">
                  <label htmlFor="type" className="form-label">
                    Appointment Type
                  </label>
                  <select
                    id="type"
                    name="type"
                    value={formData.type}
                    onChange={handleChange}
                    className="form-control"
                  >
                    {appointmentTypes.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="date" className="form-label">
                    Consultation Date
                  </label>
                  <input
                    type="date"
                    id="date"
                    name="date"
                    value={formData.date}
                    onChange={handleChange}
                    min={today}
                    className={`form-control ${errors.date ? 'error' : ''}`}
                    required
                  />
                  {errors.date && (
                    <div className="form-error">{errors.date}</div>
                  )}
                </div>

                <div className="form-group">
                  <label htmlFor="time" className="form-label">
                    Preferred Time
                  </label>
                  <select
                    id="time"
                    name="time"
                    value={formData.time}
                    onChange={handleChange}
                    className={`form-control ${errors.time ? 'error' : ''}`}
                    required
                  >
                    <option value="">Select time slot...</option>
                    {timeSlots.map(slot => (
                      <option key={slot} value={slot}>{slot}</option>
                    ))}
                  </select>
                  {errors.time && (
                    <div className="form-error">{errors.time}</div>
                  )}
                </div>
              </div>

              {/* Time Slot Visualization */}
              {formData.doctorId && formData.date && availableSlots.length > 0 && (
                <div className="form-group">
                  <label className="form-label">
                    <Clock size={18} />
                    Available Time Slots
                  </label>
                  <div className="time-slots-container">
                    {availableSlots.map(({ time, available, booked }) => (
                      <div
                        key={time}
                        className={`time-slot ${formData.time === time ? 'selected' : ''} ${
                          !available ? 'booked' : ''
                        }`}
                        onClick={() => handleTimeSlotClick(time, available && !booked)}
                      >
                        {time}
                      </div>
                    ))}
                  </div>
                  <div style={{ marginTop: '0.5rem', fontSize: '0.875rem', color: '#6b7280' }}>
                    <span style={{ color: '#10b981' }}>● Available</span>
                    <span style={{ color: '#ef4444', marginLeft: '1rem' }}>● Booked</span>
                  </div>
                </div>
              )}

              <div className="form-group">
                <label htmlFor="notes" className="form-label">
                  Medical Notes
                </label>
                <textarea
                  id="notes"
                  name="notes"
                  value={formData.notes}
                  onChange={handleChange}
                  className="form-control"
                  rows="4"
                  placeholder="Enter any medical concerns, symptoms, or special requirements for this appointment..."
                />
              </div>
            </div>

            {/* Doctor Availability Section */}
            {selectedDoctor && formData.date && (
              <div className="form-section">
                <h3>
                  <Clock size={24} />
                  Provider Availability
                </h3>
                <div className="availability-info">
                  <div className="doctor-info">
                    <strong>Dr. {selectedDoctor.name}</strong>
                    <span>{selectedDoctor.specialization}</span>
                    <span>Department: {selectedDoctor.department || 'General Medicine'}</span>
                  </div>
                  <div className="schedule-preview">
                    <Clock size={20} />
                    <span>
                      Available: {selectedDoctor.schedule?.[new Date(formData.date).getDay()]?.join(', ') || 'Not available this day'}
                    </span>
                  </div>
                </div>
              </div>
            )}

            {/* Form Actions */}
            <div className="form-actions">
              <button
                type="button"
                className="btn btn-outline"
                onClick={() => navigate('/appointments/calendar')}
                disabled={isSubmitting}
              >
                <ArrowLeft size={20} />
                Cancel
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isSubmitting}
              >
                <Save size={20} />
                {isSubmitting ? 'Scheduling Appointment...' : 'Schedule Appointment'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AppointmentScheduler;