import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Search, Filter, FileText, Download, Eye, Plus, Calendar, User, DollarSign, BarChart3, CreditCard, CheckCircle, Clock, XCircle } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './BillingHistory.css';

const BillingHistory = () => {
  const { data, updateBill } = useData();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterDate, setFilterDate] = useState('');

  const filteredBills = data.bills.filter(bill => {
    const patient = data.patients.find(p => p.id === bill.patientId);
    const matchesSearch = !searchTerm || 
      patient?.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient?.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      bill.billNumber?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesStatus = !filterStatus || bill.status === filterStatus;
    const matchesDate = !filterDate || bill.date === filterDate;
    
    return matchesSearch && matchesStatus && matchesDate;
  });

  const handleStatusUpdate = (billId, newStatus) => {
    updateBill(billId, { status: newStatus });
  };

  const formatCurrency = (value) => {
    const numValue = parseFloat(value) || 0;
    return `$${numValue.toFixed(2)}`;
  };

  const generateReceipt = (bill) => {
    const patient = data.patients.find(p => p.id === bill.patientId);
    const receiptWindow = window.open('', '_blank');
    
    const subtotal = bill.items?.reduce((sum, item) => {
      const price = parseFloat(item?.price) || 0;
      const quantity = parseInt(item?.quantity) || 1;
      return sum + (price * quantity);
    }, 0) || 0;
    
    const discountPercent = parseFloat(bill?.discount) || 0;
    const taxPercent = parseFloat(bill?.tax) || 0;
    
    const discountAmount = (subtotal * discountPercent) / 100;
    const taxAmount = (subtotal * taxPercent) / 100;
    const total = parseFloat(bill?.amount) || (subtotal - discountAmount + taxAmount);
    
    receiptWindow.document.write(`
      <html>
        <head>
          <title>Medical Receipt - ${bill.billNumber || 'N/A'}</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 0; padding: 20px; background: #f8fafc; }
            .receipt-container { max-width: 800px; margin: 0 auto; background: white; padding: 30px; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
            .header { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #e2e8f0; padding-bottom: 20px; }
            .hospital-name { color: #2563eb; font-size: 28px; font-weight: bold; margin: 0; }
            .bill-info { background: #f1f5f9; padding: 20px; border-radius: 8px; margin: 20px 0; }
            .items-table { width: 100%; border-collapse: collapse; margin: 20px 0; }
            .items-table th { background: #2563eb; color: white; padding: 12px; text-align: left; }
            .items-table td { padding: 10px 12px; border-bottom: 1px solid #e2e8f0; }
            .totals { background: #1e293b; color: white; padding: 20px; border-radius: 8px; margin-top: 20px; }
            .footer { margin-top: 30px; text-align: center; color: #64748b; font-size: 14px; }
            .status { padding: 6px 12px; border-radius: 20px; font-weight: bold; }
            .paid { background: #10b981; color: white; }
            .pending { background: #f59e0b; color: white; }
            .cancelled { background: #ef4444; color: white; }
          </style>
        </head>
        <body>
          <div class="receipt-container">
            <div class="header">
              <h1 class="hospital-name">HEALTHCARE MEDICAL CENTER</h1>
              <p><strong>Bill Number:</strong> ${bill.billNumber || 'N/A'}</p>
              <p><strong>Date:</strong> ${bill.date ? new Date(bill.date).toLocaleDateString() : new Date().toLocaleDateString()}</p>
              <span class="status ${bill.status || 'pending'}">${(bill.status || 'pending').toUpperCase()}</span>
            </div>
            
            <div class="bill-info">
              <p><strong>Patient:</strong> ${patient ? `${patient.firstName} ${patient.lastName}` : 'Unknown Patient'}</p>
              <p><strong>Payment Method:</strong> ${bill.paymentMethod || 'Not specified'}</p>
            </div>
            
            <table class="items-table">
              <thead>
                <tr>
                  <th>Service / Item</th>
                  <th>Qty</th>
                  <th>Unit Price</th>
                  <th>Amount</th>
                </tr>
              </thead>
              <tbody>
                ${(bill.items || []).map(item => {
                  const itemPrice = parseFloat(item?.price) || 0;
                  const itemQuantity = parseInt(item?.quantity) || 1;
                  const itemTotal = itemPrice * itemQuantity;
                  
                  return `
                    <tr>
                      <td>${item?.name || 'Unknown Item'}</td>
                      <td>${itemQuantity}</td>
                      <td>${formatCurrency(itemPrice)}</td>
                      <td><strong>${formatCurrency(itemTotal)}</strong></td>
                    </tr>
                  `;
                }).join('')}
              </tbody>
            </table>
            
            <div class="totals">
              <p>Subtotal: ${formatCurrency(subtotal)}</p>
              <p>Discount: -${formatCurrency(discountAmount)}</p>
              <p>Tax: ${formatCurrency(taxAmount)}</p>
              <h3>Total Amount: ${formatCurrency(total)}</h3>
            </div>
            
            <div class="footer">
              <p>Thank you for choosing our healthcare services</p>
            </div>
          </div>
        </body>
      </html>
    `);
    receiptWindow.document.close();
  };

  // Calculate statistics
  const totalRevenue = filteredBills.reduce((sum, bill) => {
    const amount = parseFloat(bill?.amount) || 0;
    return sum + amount;
  }, 0);

  const paidBills = filteredBills.filter(bill => bill.status === 'paid').length;
  const pendingBills = filteredBills.filter(bill => !bill.status || bill.status === 'pending').length;
  const cancelledBills = filteredBills.filter(bill => bill.status === 'cancelled').length;

  return (
    <div className="billing-history">
      {/* Title Bar Section */}
      <div className="title-bar">
        <div className="title-content">
          <FileText size={32} className="title-icon" />
          <h1>Medical Billing History</h1>
        </div>
      </div>

      {/* Create New Billing Section */}
      <div className="create-billing-section">
        <Link to="/billing/opd" className="create-bill-btn">
          <Plus size={20} />
          Create New Medical Bill
        </Link>
      </div>

      {/* Filters Section - Single Row */}
      <div className="filters-row">
        <div className="filter-item">
          <div className="search-box">
            <Search size={20} className="search-icon" />
            <input
              type="text"
              placeholder="Search Patient..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
        </div>

        <div className="filter-item">
          <label className="filter-label">
            <Filter size={16} />
            Bill Status
          </label>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="filter-select"
          >
            <option value="">All Status</option>
            <option value="pending">Pending</option>
            <option value="paid">Paid</option>
            <option value="cancelled">Cancelled</option>
          </select>
        </div>

        <div className="filter-item">
          <label className="filter-label">
            <Calendar size={16} />
            Bill Date
          </label>
          <input
            type="date"
            value={filterDate}
            onChange={(e) => setFilterDate(e.target.value)}
            className="filter-select"
          />
        </div>
      </div>

      {/* Billing Table Section */}
      <div className="table-section">
        <div className="table-container">
          <table className="bills-table">
            <thead>
              <tr>
                <th className="col-bill-number">Bill Number</th>
                <th className="col-patient">👤 Patient</th>
                <th className="col-date">📅 Date</th>
                <th className="col-amount">💰 Amount</th>
                <th className="col-status">📊 Status</th>
                <th className="col-payment">💳 Payment Method</th>
                <th className="col-actions">⚡ Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredBills.length > 0 ? (
                filteredBills.map(bill => {
                  const patient = data.patients.find(p => p.id === bill.patientId);
                  const billAmount = parseFloat(bill?.amount) || 0;
                  
                  return (
                    <tr key={bill.id} className="bill-row">
                      <td className="col-bill-number">
                        <strong className="bill-number">
                          {bill.billNumber || `BL${bill.id?.slice(-4) || '0000'}`}
                        </strong>
                      </td>
                      <td className="col-patient">
                        <div className="patient-info">
                          <User size={16} />
                          <span>{patient ? `${patient.firstName} ${patient.lastName}` : 'Unknown Patient'}</span>
                        </div>
                      </td>
                      <td className="col-date">
                        {bill.date ? new Date(bill.date).toLocaleDateString() : 'N/A'}
                      </td>
                      <td className="col-amount">
                        {formatCurrency(billAmount)}
                      </td>
                      <td className="col-status">
                        <span className={`status-badge ${bill.status || 'pending'}`}>
                          {bill.status === 'paid' && <CheckCircle size={12} />}
                          {bill.status === 'pending' && <Clock size={12} />}
                          {bill.status === 'cancelled' && <XCircle size={12} />}
                          {bill.status || 'pending'}
                        </span>
                      </td>
                      <td className="col-payment">
                        <span className="payment-method">
                          <CreditCard size={14} />
                          {bill.paymentMethod || 'Not specified'}
                        </span>
                      </td>

<td className="col-actions">
  <div className="action-buttons-horizontal">
    <button
      onClick={() => generateReceipt(bill)}
      className="btn btn-view btn-sm"
      title="View Receipt"
    >
      <Eye size={14} />
      View
    </button>
    {(!bill.status || bill.status === 'pending') && (
      <>
        <button
          onClick={() => handleStatusUpdate(bill.id, 'paid')}
          className="btn btn-paid btn-sm"
          title="Mark as Paid"
        >
          <CheckCircle size={14} />
          Paid
        </button>
        <button
          onClick={() => handleStatusUpdate(bill.id, 'cancelled')}
          className="btn btn-cancel btn-sm"
          title="Cancel Bill"
        >
          <XCircle size={14} />
          Cancel
        </button>
      </>
    )}
  </div>
</td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan="7" className="empty-state">
                    <div className="empty-content">
                      <FileText size={48} className="empty-icon" />
                      <h3>No Medical Bills Found</h3>
                      <p>No bills match your current search criteria</p>
                      <Link to="/billing/opd" className="btn btn-primary">
                        <Plus size={16} />
                        Create First Bill
                      </Link>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Revenue Analysis Section */}
      <div className="revenue-analysis">
        <div className="analysis-header">
          <BarChart3 size={24} />
          <h2>Revenue Analysis</h2>
        </div>
        
        <div className="analysis-grid">
          <div className="analysis-card total-revenue">
            <div className="analysis-icon">
              <DollarSign size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Total Revenue</span>
              <span className="analysis-value">{formatCurrency(totalRevenue)}</span>
            </div>
          </div>
          
          <div className="analysis-card total-bills">
            <div className="analysis-icon">
              <FileText size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Total Bills</span>
              <span className="analysis-value">{filteredBills.length}</span>
            </div>
          </div>
          
          <div className="analysis-card paid-bills">
            <div className="analysis-icon">
              <CheckCircle size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Paid Bills</span>
              <span className="analysis-value">{paidBills}</span>
            </div>
          </div>
          
          <div className="analysis-card pending-bills">
            <div className="analysis-icon">
              <Clock size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Pending Bills</span>
              <span className="analysis-value">{pendingBills}</span>
            </div>
          </div>
          
          <div className="analysis-card cancelled-bills">
            <div className="analysis-icon">
              <XCircle size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Cancelled Bills</span>
              <span className="analysis-value">{cancelledBills}</span>
            </div>
          </div>
          
          <div className="analysis-card collection-rate">
            <div className="analysis-icon">
              <BarChart3 size={20} />
            </div>
            <div className="analysis-content">
              <span className="analysis-label">Collection Rate</span>
              <span className="analysis-value">
                {filteredBills.length > 0 ? Math.round((paidBills / filteredBills.length) * 100) : 0}%
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BillingHistory;