import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  Save, 
  UserPlus, 
  ArrowLeft, 
  User, 
  Phone, 
  Mail, 
  Calendar,
  MapPin,
  Shield,
  Droplets,
  AlertTriangle,
  History,
  Heart,
  Stethoscope,
  Building
} from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './PatientRegistration.css';

const PatientRegistration = () => {
  const { addPatient } = useData();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    phone: '',
    email: '',
    dob: '',
    gender: '',
    address: '',
    emergencyContact: '',
    bloodGroup: '',
    allergies: '',
    medicalHistory: ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  const validateForm = () => {
    const newErrors = {};
    
    if (!formData.firstName.trim()) newErrors.firstName = 'First name is required';
    if (!formData.lastName.trim()) newErrors.lastName = 'Last name is required';
    if (!formData.phone.trim()) newErrors.phone = 'Phone number is required';
    if (!formData.dob) newErrors.dob = 'Date of birth is required';
    if (!formData.gender) newErrors.gender = 'Gender is required';
    
    // Phone validation
    const phoneRegex = /^\+?[\d\s-()]{10,}$/;
    if (formData.phone && !phoneRegex.test(formData.phone.replace(/\s/g, ''))) {
      newErrors.phone = 'Please enter a valid phone number (min 10 digits)';
    }
    
    // Email validation
    if (formData.email && !/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    // Date validation
    if (formData.dob) {
      const dobDate = new Date(formData.dob);
      const today = new Date();
      if (dobDate > today) {
        newErrors.dob = 'Date of birth cannot be in the future';
      }
      
      // Check if age is reasonable (between 0 and 150 years)
      const age = today.getFullYear() - dobDate.getFullYear();
      if (age > 150) {
        newErrors.dob = 'Please enter a valid date of birth';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Clear error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      // Scroll to first error
      const firstError = Object.keys(errors)[0];
      if (firstError) {
        const element = document.getElementById(firstError);
        element?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        element?.focus();
      }
      return;
    }

    setIsSubmitting(true);
    setSuccess(false);
    
    // Simulate API call delay
    setTimeout(() => {
      const newPatient = addPatient(formData);
      setIsSubmitting(false);
      setSuccess(true);
      
      // Show success message
      alert(`✅ Patient registered successfully!\nPatient ID: PT${newPatient.id.slice(-4)}\nName: ${formData.firstName} ${formData.lastName}`);
      
      // Reset form
      setFormData({
        firstName: '',
        lastName: '',
        phone: '',
        email: '',
        dob: '',
        gender: '',
        address: '',
        emergencyContact: '',
        bloodGroup: '',
        allergies: '',
        medicalHistory: ''
      });
      
      // Navigate to patient list after a delay
      setTimeout(() => {
        navigate('/patients/list');
      }, 2000);
    }, 1500);
  };

  return (
    <div className="patient-registration">
      {/* Header Section */}
      <div className="page-header">
        <div className="header-left">
          <Link to="/patients/list" className="btn btn-outline">
            <ArrowLeft size={20} />
            Back to Patients
          </Link>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative' }}>
  <UserPlus 
  size={28} 
  style={{ 
    position: 'absolute',
    left: '180px',
    color: 'white'
  }} 
/>
  <h1 style={{ 
  marginLeft: '220px',
  color: 'white'
}}>
  Patient Registration
</h1>
</div>
        </div>
      </div>

      {/* Main Form Card */}
      <div className={`registration-card ${success ? 'success-animation' : ''}`}>
        <div className="card-header">
          <div className="header-title">
            <Building size={32} color="white" />
            <h2>New Patient Registration Form</h2>
          </div>
          <p className="text-muted">
            Please fill in all required fields marked with *. Ensure all information is accurate and complete.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="registration-form">
          {/* Personal Information Section */}
          <div className="form-section">
            <h3>
              <User size={24} />
              Personal Information
            </h3>
            
            <div className="form-row">
              {/* First Name Field */}
              <div className="form-group">
                <label htmlFor="firstName" className="form-label">
                  <User size={18} />
                  First Name
                </label>
                <input
                  type="text"
                  id="firstName"
                  name="firstName"
                  value={formData.firstName}
                  onChange={handleChange}
                  className={`form-control ${errors.firstName ? 'error' : ''}`}
                  placeholder="Enter patient's first name"
                  required
                />
                {errors.firstName && (
                  <div className="form-error">{errors.firstName}</div>
                )}
              </div>

              {/* Last Name Field */}
              <div className="form-group">
                <label htmlFor="lastName" className="form-label">
                  <User size={18} />
                  Last Name
                </label>
                <input
                  type="text"
                  id="lastName"
                  name="lastName"
                  value={formData.lastName}
                  onChange={handleChange}
                  className={`form-control ${errors.lastName ? 'error' : ''}`}
                  placeholder="Enter patient's last name"
                  required
                />
                {errors.lastName && (
                  <div className="form-error">{errors.lastName}</div>
                )}
              </div>
            </div>

            <div className="form-row">
              {/* Phone Field */}
              <div className="form-group">
                <label htmlFor="phone" className="form-label">
                  <Phone size={18} />
                  Phone Number
                </label>
                <input
                  type="tel"
                  id="phone"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  className={`form-control ${errors.phone ? 'error' : ''}`}
                  placeholder="+1 (555) 012-3456"
                  required
                />
                {errors.phone && (
                  <div className="form-error">{errors.phone}</div>
                )}
              </div>

              {/* Email Field */}
              <div className="form-group">
                <label htmlFor="email" className="form-label">
                  <Mail size={18} />
                  Email Address
                </label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  className={`form-control ${errors.email ? 'error' : ''}`}
                  placeholder="patient@example.com"
                />
                {errors.email && (
                  <div className="form-error">{errors.email}</div>
                )}
              </div>
            </div>

            <div className="form-row">
              {/* Date of Birth Field */}
              <div className="form-group">
                <label htmlFor="dob" className="form-label">
                  <Calendar size={18} />
                  Date of Birth
                </label>
                <input
                  type="date"
                  id="dob"
                  name="dob"
                  value={formData.dob}
                  onChange={handleChange}
                  className={`form-control ${errors.dob ? 'error' : ''}`}
                  required
                />
                {errors.dob && (
                  <div className="form-error">{errors.dob}</div>
                )}
              </div>

              {/* Gender Field */}
              <div className="form-group">
                <label htmlFor="gender" className="form-label">
                  <User size={18} />
                  Gender
                </label>
                <select
                  id="gender"
                  name="gender"
                  value={formData.gender}
                  onChange={handleChange}
                  className={`form-control ${errors.gender ? 'error' : ''}`}
                  required
                >
                  <option value="">Select Gender</option>
                  <option value="Male">Male</option>
                  <option value="Female">Female</option>
                  <option value="Other">Other</option>
                  <option value="Prefer not to say">Prefer not to say</option>
                </select>
                {errors.gender && (
                  <div className="form-error">{errors.gender}</div>
                )}
              </div>
            </div>

            {/* Address Field */}
            <div className="form-group">
              <label htmlFor="address" className="form-label">
                <MapPin size={18} />
                Full Address
              </label>
              <textarea
                id="address"
                name="address"
                value={formData.address}
                onChange={handleChange}
                className="form-control"
                rows="3"
                placeholder="Enter complete address including street, city, state, and postal code"
              />
            </div>
          </div>

          {/* Medical Information Section */}
          <div className="form-section">
            <h3>
              <Stethoscope size={24} />
              Medical Information
            </h3>
            
            <div className="form-row">
              {/* Blood Group Field */}
              <div className="form-group">
                <label htmlFor="bloodGroup" className="form-label">
                  <Droplets size={18} />
                  Blood Group
                </label>
                <select
                  id="bloodGroup"
                  name="bloodGroup"
                  value={formData.bloodGroup}
                  onChange={handleChange}
                  className="form-control"
                >
                  <option value="">Select Blood Group</option>
                  <option value="A+">A Positive (A+)</option>
                  <option value="A-">A Negative (A-)</option>
                  <option value="B+">B Positive (B+)</option>
                  <option value="B-">B Negative (B-)</option>
                  <option value="O+">O Positive (O+)</option>
                  <option value="O-">O Negative (O-)</option>
                  <option value="AB+">AB Positive (AB+)</option>
                  <option value="AB-">AB Negative (AB-)</option>
                </select>
              </div>

              {/* Emergency Contact Field */}
              <div className="form-group">
                <label htmlFor="emergencyContact" className="form-label">
                  <Heart size={18} />
                  Emergency Contact
                </label>
                <input
                  type="text"
                  id="emergencyContact"
                  name="emergencyContact"
                  value={formData.emergencyContact}
                  onChange={handleChange}
                  className="form-control"
                  placeholder="Emergency contact name and phone number"
                />
              </div>
            </div>

            {/* Allergies Field */}
            <div className="form-group">
              <label htmlFor="allergies" className="form-label">
                <AlertTriangle size={18} />
                Known Allergies
              </label>
              <input
                type="text"
                id="allergies"
                name="allergies"
                value={formData.allergies}
                onChange={handleChange}
                className="form-control"
                placeholder="List any known allergies (e.g., Penicillin, Peanuts, Latex, etc.)"
              />
            </div>

            {/* Medical History Field */}
            <div className="form-group">
              <label htmlFor="medicalHistory" className="form-label">
                <History size={18} />
                Medical History
              </label>
              <textarea
                id="medicalHistory"
                name="medicalHistory"
                value={formData.medicalHistory}
                onChange={handleChange}
                className="form-control"
                rows="4"
                placeholder="Include previous medical conditions, surgeries, chronic illnesses, current medications, family medical history, etc."
              />
            </div>
          </div>

          {/* Form Actions */}
          <div className="form-actions">
            <button
              type="button"
              className="btn btn-outline"
              onClick={() => navigate('/patients/list')}
              disabled={isSubmitting}
            >
              <ArrowLeft size={20} />
              Cancel Registration
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isSubmitting}
            >
              <Save size={20} />
              {isSubmitting ? 'Registering Patient...' : 'Register Patient'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default PatientRegistration;