import React, { useState } from 'react';
import { Search, Filter, Pill, Plus, AlertTriangle, Package, TrendingUp, Users, DollarSign } from 'lucide-react';
import { useData } from '../../utils/DataContext';
import './PharmacyManagement.css';

const PharmacyManagement = () => {
  const { data } = useData();
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [lowStockOnly, setLowStockOnly] = useState(false);

  const medicineCategories = [
    'All Categories',
    'Analgesics',
    'Antibiotics',
    'Antihypertensives',
    'Vitamins',
    'Antidiabetics',
    'Antidepressants',
    'Gastrointestinal',
    'Respiratory',
    'Others'
  ];

  // Enhanced medicines data
  const enhancedMedicines = [
    ...data.medicines,
    {
      id: 101,
      name: 'Aspirin',
      category: 'Analgesics',
      price: 5.99,
      stock: 45,
      expiryDate: '2024-12-15'
    },
    {
      id: 102,
      name: 'Vitamin C',
      category: 'Vitamins',
      price: 8.50,
      stock: 100,
      expiryDate: '2025-03-20'
    },
    {
      id: 103,
      name: 'Metformin',
      category: 'Antidiabetics',
      price: 12.75,
      stock: 8,
      expiryDate: '2024-08-30'
    },
    {
      id: 104,
      name: 'Omeprazole',
      category: 'Gastrointestinal',
      price: 15.25,
      stock: 25,
      expiryDate: '2024-11-10'
    },
    {
      id: 105,
      name: 'Ventolin',
      category: 'Respiratory',
      price: 18.99,
      stock: 0,
      expiryDate: '2024-09-05'
    },
    {
      id: 106,
      name: 'Sertraline',
      category: 'Antidepressants',
      price: 22.50,
      stock: 15,
      expiryDate: '2025-01-15'
    },
    {
      id: 107,
      name: 'Atorvastatin',
      category: 'Antihypertensives',
      price: 14.99,
      stock: 32,
      expiryDate: '2024-10-25'
    },
    {
      id: 108,
      name: 'Cephalexin',
      category: 'Antibiotics',
      price: 11.25,
      stock: 5,
      expiryDate: '2024-07-18'
    }
  ];

  const filteredMedicines = enhancedMedicines.filter(medicine => {
    const matchesSearch = !searchTerm || 
      medicine.name.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesCategory = !filterCategory || filterCategory === 'All Categories' || 
      medicine.category === filterCategory;
    
    const matchesStock = !lowStockOnly || medicine.stock < 20;
    
    return matchesSearch && matchesCategory && matchesStock;
  });

  const getStockStatus = (stock) => {
    if (stock === 0) return { color: 'badge-error', text: 'Out of Stock', bgColor: '#fee2e2', borderColor: '#fecaca' };
    if (stock < 10) return { color: 'badge-warning', text: 'Low Stock', bgColor: '#fffbeb', borderColor: '#fed7aa' };
    if (stock < 20) return { color: 'badge-info', text: 'Adequate', bgColor: '#eff6ff', borderColor: '#bfdbfe' };
    return { color: 'badge-success', text: 'In Stock', bgColor: '#f0fdf4', borderColor: '#bbf7d0' };
  };

  // Enhanced recent transactions
  const recentTransactions = [
    {
      id: 1,
      medicine: 'Paracetamol',
      patient: 'John Doe',
      quantity: 2,
      date: '2024-01-20',
      amount: 10,
      type: 'sale'
    },
    {
      id: 2,
      medicine: 'Amoxicillin',
      patient: 'Sarah Wilson',
      quantity: 1,
      date: '2024-01-19',
      amount: 12,
      type: 'sale'
    },
    {
      id: 3,
      medicine: 'Ibuprofen',
      patient: 'Robert Johnson',
      quantity: 1,
      date: '2024-01-18',
      amount: 8,
      type: 'sale'
    },
    {
      id: 4,
      medicine: 'Vitamin C',
      patient: 'Emily Brown',
      quantity: 3,
      date: '2024-01-18',
      amount: 25.50,
      type: 'sale'
    },
    {
      id: 5,
      medicine: 'Aspirin',
      patient: 'Michael Davis',
      quantity: 2,
      date: '2024-01-17',
      amount: 11.98,
      type: 'sale'
    },
    {
      id: 6,
      medicine: 'Metformin',
      patient: 'Lisa Anderson',
      quantity: 1,
      date: '2024-01-17',
      amount: 12.75,
      type: 'sale'
    }
  ];

  // Enhanced inventory summary
  const inventoryStats = {
    totalMedicines: enhancedMedicines.length,
    lowStock: enhancedMedicines.filter(m => m.stock < 10).length,
    outOfStock: enhancedMedicines.filter(m => m.stock === 0).length,
    totalValue: enhancedMedicines.reduce((sum, med) => sum + (med.price * med.stock), 0),
    totalCategories: new Set(enhancedMedicines.map(m => m.category)).size
  };

  return (
    <div className="pharmacy-management">
      <div className="page-header">
        <h1>Pharmacy Management</h1>
        <p className="text-muted">Manage medicine inventory and sales</p>
      </div>

      <div className="pharmacy-content">
        <div className="pharmacy-main">
          {/* Enhanced Filters Section */}
          <div className="filters-card">
            <div className="search-box">
              <Search size={20} className="search-icon" />
              <input
                type="text"
                placeholder="Search medicines by name..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="search-input"
              />
            </div>
            
            <div className="filter-group">
              <label className="filter-label">Category</label>
              <select
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
                className="filter-select"
              >
                {medicineCategories.map(category => (
                  <option key={category} value={category}>{category}</option>
                ))}
              </select>
            </div>

            <div className="filter-group">
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={lowStockOnly}
                  onChange={(e) => setLowStockOnly(e.target.checked)}
                  className="checkbox"
                />
                Show Low Stock Only
              </label>
            </div>

            <div className="filter-group">
              <button className="btn btn-outline">
                <Filter size={16} />
                Advanced Filters
              </button>
            </div>
          </div>

          {/* Enhanced Inventory Grid */}
          <div className="inventory-section">
            <div className="section-header">
              <h2>Medicine Inventory</h2>
              <span className="item-count">{filteredMedicines.length} medicines found</span>
            </div>
            
            <div className="inventory-grid">
              {filteredMedicines.map(medicine => {
                const stockStatus = getStockStatus(medicine.stock);
                return (
                  <div 
                    key={medicine.id} 
                    className="medicine-card"
                    style={{ 
                      backgroundColor: stockStatus.bgColor,
                      border: `2px solid ${stockStatus.borderColor}`
                    }}
                  >
                    <div className="medicine-header">
                      <div className="medicine-icon">
                        <Pill size={20} />
                      </div>
                      <div className="medicine-info">
                        <h3>{medicine.name}</h3>
                        <span className="medicine-category">{medicine.category}</span>
                      </div>
                      {medicine.stock < 10 && (
                        <AlertTriangle size={18} className="low-stock-icon" />
                      )}
                    </div>

                    <div className="medicine-details">
                      <div className="detail-row">
                        <span>Price:</span>
                        <strong>${medicine.price.toFixed(2)}</strong>
                      </div>
                      <div className="detail-row">
                        <span>Stock Level:</span>
                        <div className="stock-info">
                          <span className="stock-quantity">{medicine.stock} units</span>
                          <span className={`badge ${stockStatus.color}`}>
                            {stockStatus.text}
                          </span>
                        </div>
                      </div>
                      {medicine.expiryDate && (
                        <div className="detail-row">
                          <span>Expiry Date:</span>
                          <span className={new Date(medicine.expiryDate) < new Date(Date.now() + 90*24*60*60*1000) ? 'expiry-soon' : ''}>
                            {medicine.expiryDate}
                          </span>
                        </div>
                      )}
                      <div className="detail-row">
                        <span>Total Value:</span>
                        <strong>${(medicine.price * medicine.stock).toFixed(2)}</strong>
                      </div>
                    </div>

                    <div className="medicine-actions">
                      <button className="btn btn-outline btn-sm">
                        <Plus size={14} />
                        Restock
                      </button>
                      <button 
                        className="btn btn-primary btn-sm"
                        disabled={medicine.stock === 0}
                      >
                        Sell Medicine
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Enhanced Sidebar */}
        <div className="pharmacy-sidebar">
          {/* Enhanced Inventory Summary */}
          <div className="sidebar-card summary-card">
            <h3>
              <Package size={20} />
              Inventory Summary
            </h3>
            <div className="inventory-stats">
              <div className="stat-item total-medicines">
                <div className="stat-icon">
                  <Pill size={24} />
                </div>
                <div className="stat-content">
                  <span className="stat-number">{inventoryStats.totalMedicines}</span>
                  <span className="stat-label">Total Medicines</span>
                </div>
              </div>
              <div className="stat-item categories">
                <div className="stat-icon">
                  <Filter size={24} />
                </div>
                <div className="stat-content">
                  <span className="stat-number">{inventoryStats.totalCategories}</span>
                  <span className="stat-label">Categories</span>
                </div>
              </div>
              <div className="stat-item low-stock">
                <div className="stat-icon">
                  <AlertTriangle size={24} />
                </div>
                <div className="stat-content">
                  <span className="stat-number">{inventoryStats.lowStock}</span>
                  <span className="stat-label">Low Stock Items</span>
                </div>
              </div>
              <div className="stat-item out-of-stock">
                <div className="stat-icon">
                  <AlertTriangle size={24} />
                </div>
                <div className="stat-content">
                  <span className="stat-number">{inventoryStats.outOfStock}</span>
                  <span className="stat-label">Out of Stock</span>
                </div>
              </div>
              <div className="stat-item total-value">
                <div className="stat-icon">
                  <DollarSign size={24} />
                </div>
                <div className="stat-content">
                  <span className="stat-number">${inventoryStats.totalValue.toFixed(2)}</span>
                  <span className="stat-label">Total Inventory Value</span>
                </div>
              </div>
            </div>
          </div>

          {/* Enhanced Recent Sales */}
          <div className="sidebar-card sales-card">
            <h3>
              <TrendingUp size={20} />
              Recent Sales
            </h3>
            <div className="sales-list">
              {recentTransactions.map(transaction => (
                <div key={transaction.id} className="sale-item">
                  <div className="sale-icon">
                    <Pill size={16} />
                  </div>
                  <div className="sale-info">
                    <strong>{transaction.medicine}</strong>
                    <span>
                      <Users size={12} />
                      {transaction.patient}
                    </span>
                  </div>
                  <div className="sale-details">
                    <span>Qty: {transaction.quantity}</span>
                    <strong>${transaction.amount}</strong>
                  </div>
                </div>
              ))}
            </div>
            <div className="view-all">
              <button className="btn btn-link">View All Transactions</button>
            </div>
          </div>

          {/* Enhanced Quick Actions */}
          <div className="sidebar-card actions-card">
            <h3>Quick Actions</h3>
            <div className="quick-actions">
              <button className="btn btn-primary btn-block">
                <Plus size={16} />
                Add New Medicine
              </button>
              <button className="btn btn-secondary btn-block">
                <Package size={16} />
                Generate Inventory Report
              </button>
              <button className="btn btn-secondary btn-block">
                <TrendingUp size={16} />
                Sales Report
              </button>
              <button className="btn btn-outline btn-block">
                <DollarSign size={16} />
                Process Sale
              </button>
              <button className="btn btn-outline btn-block">
                <Plus size={16} />
                Bulk Restock
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PharmacyManagement;