// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { DataProvider } from './utils/DataContext'; // Correct import from utils folder
import Layout from './components/common/Layout';
import Dashboard from './components/dashboard/Dashboard';
import PatientRegistration from './components/patients/PatientRegistration';
import PatientList from './components/patients/PatientList';
import AppointmentScheduler from './components/appointments/AppointmentScheduler';
import AppointmentCalendar from './components/appointments/AppointmentCalendar';
import OPDBilling from './components/billing/OPDBilling';
import BillingHistory from './components/billing/BillingHistory';
import DoctorManagement from './components/doctors/DoctorManagement';
import LabManagement from './components/labs/LabManagement';
import PharmacyManagement from './components/pharmacy/PharmacyManagement';
import Reports from './components/reports/Reports';
import Settings from './components/settings/Settings';
import ContactUs from './components/common/ContactUs'; // New component for Contact Us
import Gallery from './components/common/Gallery'; // New component for Gallery
import './styles/global.css';

function App() {
  return (
    <DataProvider>
      <Router>
        <div className="App">
          <Layout>
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/dashboard" element={<Dashboard />} />
              <Route path="/patients/registration" element={<PatientRegistration />} />
              <Route path="/patients/list" element={<PatientList />} />
              <Route path="/appointments/schedule" element={<AppointmentScheduler />} />
              <Route path="/appointments/calendar" element={<AppointmentCalendar />} />
              <Route path="/billing/opd" element={<OPDBilling />} />
              <Route path="/billing/history" element={<BillingHistory />} />
              <Route path="/doctors" element={<DoctorManagement />} />
              <Route path="/labs" element={<LabManagement />} />
              <Route path="/pharmacy" element={<PharmacyManagement />} />
              <Route path="/reports" element={<Reports />} />
              <Route path="/settings" element={<Settings />} />
              <Route path="/contact" element={<ContactUs />} /> {/* New Contact Us route */}
              <Route path="/gallery" element={<Gallery />} /> {/* New Gallery route */}
              <Route path="*" element={<Dashboard />} />
            </Routes>
          </Layout>
        </div>
      </Router>
    </DataProvider>
  );
}

export default App;