import React, { createContext, useContext, useState, useEffect } from 'react';
import { initialData } from '../data/initialData';

const DataContext = createContext();

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

export const DataProvider = ({ children }) => {
  const [data, setData] = useState(() => {
    const saved = localStorage.getItem('hims-data');
    return saved ? JSON.parse(saved) : initialData;
  });

  useEffect(() => {
    localStorage.setItem('hims-data', JSON.stringify(data));
  }, [data]);

  const addPatient = (patient) => {
    const newPatient = {
      ...patient,
      id: Date.now().toString(),
      patientId: `PT${String(data.patients.length + 1).padStart(3, '0')}`,
      registrationDate: new Date().toISOString().split('T')[0]
    };
    setData(prev => ({
      ...prev,
      patients: [...prev.patients, newPatient]
    }));
    return newPatient;
  };

  const updatePatient = (id, updates) => {
    setData(prev => ({
      ...prev,
      patients: prev.patients.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const addAppointment = (appointment) => {
    const newAppointment = {
      ...appointment,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    setData(prev => ({
      ...prev,
      appointments: [...prev.appointments, newAppointment]
    }));
    return newAppointment;
  };

  const updateAppointment = (id, updates) => {
    setData(prev => ({
      ...prev,
      appointments: prev.appointments.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  };

  const addBill = (bill) => {
    const newBill = {
      ...bill,
      id: Date.now().toString(),
      billNumber: `BL${String(data.bills.length + 1).padStart(3, '0')}`,
      createdAt: new Date().toISOString()
    };
    setData(prev => ({
      ...prev,
      bills: [...prev.bills, newBill]
    }));
    return newBill;
  };

  const updateBill = (id, updates) => {
    setData(prev => ({
      ...prev,
      bills: prev.bills.map(b => b.id === id ? { ...b, ...updates } : b)
    }));
  };

  const value = {
    data,
    setData,
    addPatient,
    updatePatient,
    addAppointment,
    updateAppointment,
    addBill,
    updateBill
  };

  return (
    <DataContext.Provider value={value}>
      {children}
    </DataContext.Provider>
  );
};